// CAN CHINH SUA O DAY: dien list ID that + kiem tra lai ten custom field cho khop ClickUp thuc te
// (mo task bat ky trong list -> xem cot custom field ben phai de lay dung TEN, khong can ID)
const config = {
  team_id: "9018351620", // team ID dung chung, da biet tu cac node cr_task_hs/cr_task_dh

  // Danh sach List can dong bo. Them/bot dong tuy y, khong can sua code o duoi.
  lists: [
    { listId: "901805909593", listName: "List 2025" },
    { listId: "901805909357", listName: "Orders" },
    // { listId: "REPLACE_LIST_ID_2026", listName: "List 2026" },
    // { listId: "REPLACE_LIST_ID_ELMC", listName: "ELMC" },
    // { listId: "REPLACE_LIST_ID_ELHZ", listName: "ELHZ" },
    // { listId: "REPLACE_LIST_ID_ELHT", listName: "ELHT" },
  ],

  // Map ten cot Postgres -> TEN custom field trong ClickUp (khong phai ID).
  // DAY LA PHONG DOAN dua theo cach dat ten trong code Telebot cu - CAN ANH KIEM TRA LAI
  // cho khop chinh xac voi ten field that trong ClickUp cua anh.
  fieldNameMap: {
    phu_trach:     "Phụ trách",
    dkpv:          "DKPV",
    pvtc:          "PVTC",
    vfs:           "VFS",
    planbay:       "Plan bay",
    ngaybay:       "Ngày bay",
    youtube_link:  "Youtube",
    onedrive_link: "OneDrive",
    other_link:    "Link khác",
    color:         "Color",
  }
};

return [{ json: config }];

// Map 1 ClickUp task -> 1 dong Postgres. Doc ten custom field tu Config (khong hardcode ID).
const fieldNameMap = $('⚙️ Config').first().json.fieldNameMap;
const currentList = $('Loop Over Lists').first().json; // { listId, listName }

const normalize = (s) => (s || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\u0111/g, 'd')
  .replace(/\u0110/g, 'D')
  .toLowerCase();

function getCF(customFields, name) {
  if (!Array.isArray(customFields) || !name) return null;
  const f = customFields.find(cf => (cf.name || '').trim().toLowerCase() === name.trim().toLowerCase());
  if (!f || f.value === undefined || f.value === null) return null;
  // Neu la timestamp dang ms (field kieu date) -> format dd/mm/yyyy, con lai tra ve string tho
  if (/^\d{10,13}$/.test(String(f.value))) {
    const d = new Date(Number(f.value));
    if (!isNaN(d.getTime())) {
      const dd = String(d.getDate()).padStart(2, '0');
      const mm = String(d.getMonth() + 1).padStart(2, '0');
      const yyyy = d.getFullYear();
      return `${dd}/${mm}/${yyyy}`;
    }
  }
  if (typeof f.value === 'object') return JSON.stringify(f.value);
  return String(f.value);
}

const items = $input.all();
return items.map(it => {
  const t = it.json;
  const cfs = t.custom_fields || [];

  // phu_trach: uu tien custom field, fallback sang assignee dau tien neu khong co field rieng
  let phuTrach = getCF(cfs, fieldNameMap.phu_trach);
  if (!phuTrach && Array.isArray(t.assignees) && t.assignees.length > 0) {
    phuTrach = t.assignees.map(a => a.username || a.email).filter(Boolean).join(', ');
  }

  return {
    json: {
      id: t.id,
      name: t.name || '',
      name_khong_dau: normalize(t.name || ''),
      url: t.url || '',
      description: t.text_content || t.description || '',
      status: t.status?.status || '',
      phu_trach: phuTrach || '',
      dkpv: getCF(cfs, fieldNameMap.dkpv) || '',
      pvtc: getCF(cfs, fieldNameMap.pvtc) || '',
      folder_name: t.folder?.name || '',
      list_name: currentList.listName || t.list?.name || '',
      vfs: getCF(cfs, fieldNameMap.vfs) || '',
      planbay: getCF(cfs, fieldNameMap.planbay) || '',
      ngaybay: getCF(cfs, fieldNameMap.ngaybay) || '',
      youtube_link: getCF(cfs, fieldNameMap.youtube_link) || '',
      onedrive_link: getCF(cfs, fieldNameMap.onedrive_link) || '',
      color: getCF(cfs, fieldNameMap.color) || '',
      other_link: getCF(cfs, fieldNameMap.other_link) || '',
      date_updated: t.date_updated ? new Date(Number(t.date_updated)).toISOString() : null,
    }
  };
});
